-- =====================================================================
-- FARM2HOME AI — Database schema + sample data
-- MySQL 8.0+ / MariaDB 10.6+  ·  charset utf8mb4
-- Tài khoản mẫu: admin@farm2home.vn / password  ·  operator@farm2home.vn / password
-- =====================================================================

SET NAMES utf8mb4;
SET time_zone = '+07:00';
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `farm2home` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `farm2home`;

-- ---------------------------------------------------------------------
-- 0. Laravel core tables (users, sessions, cache)
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(20) NULL,
  `role` ENUM('admin','operator') NOT NULL DEFAULT 'operator',
  `email_verified_at` TIMESTAMP NULL,
  `password` VARCHAR(255) NOT NULL,
  `remember_token` VARCHAR(100) NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (
  `email` VARCHAR(255) NOT NULL,
  `token` VARCHAR(255) NOT NULL,
  `created_at` TIMESTAMP NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` VARCHAR(255) NOT NULL,
  `user_id` BIGINT UNSIGNED NULL,
  `ip_address` VARCHAR(45) NULL,
  `user_agent` TEXT NULL,
  `payload` LONGTEXT NOT NULL,
  `last_activity` INT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (
  `key` VARCHAR(255) NOT NULL,
  `value` MEDIUMTEXT NOT NULL,
  `expiration` INT NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (
  `key` VARCHAR(255) NOT NULL,
  `owner` VARCHAR(255) NOT NULL,
  `expiration` INT NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 1. Master data
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `delivery_zones`;
CREATE TABLE `delivery_zones` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL COMMENT 'Tên cụm giao hàng',
  `description` VARCHAR(255) NULL COMMENT 'Phường/xã thuộc cụm',
  `shipping_fee` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'VND',
  `free_ship_from` INT UNSIGNED NULL COMMENT 'Miễn phí ship khi đơn >= (VND)',
  `pickup_point` VARCHAR(255) NULL COMMENT 'Điểm nhận tập trung',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `farmers`;
CREATE TABLE `farmers` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(20) NOT NULL COMMENT 'VD: NH01',
  `name` VARCHAR(150) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `zalo_phone` VARCHAR(20) NULL,
  `address` VARCHAR(255) NULL,
  `growing_area` VARCHAR(255) NULL COMMENT 'Khu vực trồng hiển thị trên QR',
  `area_m2` INT UNSIGNED NULL,
  `farming_method` VARCHAR(150) NULL COMMENT 'VD: Canh tác theo hướng an toàn',
  `certificate_name` VARCHAR(150) NULL COMMENT 'Chỉ điền khi có giấy tờ xác thực',
  `certificate_file` VARCHAR(255) NULL,
  `certificate_expires_at` DATE NULL,
  `access_token` CHAR(40) NOT NULL COMMENT 'Token cho link báo sản lượng (không cần login)',
  `status` ENUM('active','paused','inactive') NOT NULL DEFAULT 'active',
  `note` TEXT NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `farmers_code_unique` (`code`),
  UNIQUE KEY `farmers_access_token_unique` (`access_token`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(10) NOT NULL COMMENT 'Dùng trong mã lô, VD: RM',
  `name` VARCHAR(150) NOT NULL,
  `slug` VARCHAR(160) NOT NULL,
  `pack_weight_kg` DECIMAL(6,3) NOT NULL DEFAULT 0.500 COMMENT 'Khối lượng 1 gói',
  `price` INT UNSIGNED NOT NULL COMMENT 'Giá bán / gói (VND)',
  `cost_price_per_kg` INT UNSIGNED NOT NULL COMMENT 'Giá thu mua / kg (VND)',
  `shelf_life_days` TINYINT UNSIGNED NOT NULL DEFAULT 3,
  `storage_guide` TEXT NULL,
  `image` VARCHAR(255) NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_code_unique` (`code`),
  UNIQUE KEY `products_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `farmer_products`;
CREATE TABLE `farmer_products` (
  `farmer_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `typical_weekly_kg` DECIMAL(8,2) NULL COMMENT 'Năng lực cung ứng ước tính / tuần',
  PRIMARY KEY (`farmer_id`,`product_id`),
  CONSTRAINT `fp_farmer_fk` FOREIGN KEY (`farmer_id`) REFERENCES `farmers`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fp_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `baskets`;
CREATE TABLE `baskets` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(150) NOT NULL,
  `slug` VARCHAR(160) NOT NULL,
  `description` TEXT NULL,
  `household_min` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `household_max` TINYINT UNSIGNED NOT NULL DEFAULT 2,
  `price` INT UNSIGNED NOT NULL COMMENT 'Giá / giỏ (VND)',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `baskets_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `basket_items`;
CREATE TABLE `basket_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `basket_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `quantity` SMALLINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Số gói',
  `allow_substitute` TINYINT(1) NOT NULL DEFAULT 1 COMMENT 'Cho phép đổi rau tương đương khi thiếu',
  PRIMARY KEY (`id`),
  UNIQUE KEY `basket_product_unique` (`basket_id`,`product_id`),
  CONSTRAINT `bi_basket_fk` FOREIGN KEY (`basket_id`) REFERENCES `baskets`(`id`) ON DELETE CASCADE,
  CONSTRAINT `bi_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 2. Phía cầu: khách hàng, giỏ định kỳ, đơn hàng
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `customers`;
CREATE TABLE `customers` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(150) NOT NULL,
  `phone` VARCHAR(20) NOT NULL COMMENT 'Định danh khách, không cần login',
  `zalo_phone` VARCHAR(20) NULL,
  `address` VARCHAR(255) NULL,
  `delivery_zone_id` BIGINT UNSIGNED NULL,
  `household_size` TINYINT UNSIGNED NULL,
  `budget_per_week` INT UNSIGNED NULL,
  `preferences` JSON NULL COMMENT 'Nhóm rau ưa thích do khách tự chọn',
  `source` ENUM('zalo','form','website','phone','referral') NOT NULL DEFAULT 'zalo',
  `data_consent` TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'Đồng ý dùng dữ liệu cho vận hành',
  `note` TEXT NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customers_phone_unique` (`phone`),
  CONSTRAINT `cus_zone_fk` FOREIGN KEY (`delivery_zone_id`) REFERENCES `delivery_zones`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `subscriptions`;
CREATE TABLE `subscriptions` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `basket_id` BIGINT UNSIGNED NOT NULL,
  `frequency` ENUM('weekly','biweekly','monthly') NOT NULL DEFAULT 'weekly',
  `delivery_weekday` TINYINT UNSIGNED NOT NULL COMMENT '1=Thứ 2 ... 7=Chủ nhật',
  `time_slot` VARCHAR(20) NOT NULL DEFAULT '17:00-19:00',
  `start_date` DATE NOT NULL,
  `end_date` DATE NULL,
  `status` ENUM('active','paused','cancelled') NOT NULL DEFAULT 'active',
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  KEY `sub_status_idx` (`status`,`delivery_weekday`),
  CONSTRAINT `sub_customer_fk` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE CASCADE,
  CONSTRAINT `sub_basket_fk` FOREIGN KEY (`basket_id`) REFERENCES `baskets`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(30) NOT NULL COMMENT 'VD: DH260930-001',
  `customer_id` BIGINT UNSIGNED NOT NULL,
  `subscription_id` BIGINT UNSIGNED NULL,
  `delivery_zone_id` BIGINT UNSIGNED NULL,
  `order_type` ENUM('basket','single') NOT NULL,
  `channel` ENUM('zalo','form','website','phone') NOT NULL DEFAULT 'zalo',
  `delivery_date` DATE NOT NULL,
  `time_slot` VARCHAR(20) NOT NULL DEFAULT '17:00-19:00',
  `delivery_method` ENUM('home','pickup') NOT NULL DEFAULT 'home',
  `delivery_address` VARCHAR(255) NULL,
  `subtotal` INT UNSIGNED NOT NULL DEFAULT 0,
  `shipping_fee` INT UNSIGNED NOT NULL DEFAULT 0,
  `discount` INT UNSIGNED NOT NULL DEFAULT 0,
  `total` INT UNSIGNED NOT NULL DEFAULT 0,
  `payment_method` ENUM('cod','bank_transfer') NOT NULL DEFAULT 'cod',
  `payment_status` ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',
  `status` ENUM('pending','confirmed','packing','delivering','delivered','cancelled') NOT NULL DEFAULT 'pending',
  `confirmed_at` TIMESTAMP NULL,
  `delivered_at` TIMESTAMP NULL,
  `cancel_reason` VARCHAR(255) NULL,
  `note` TEXT NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_code_unique` (`code`),
  KEY `orders_delivery_idx` (`delivery_date`,`status`),
  CONSTRAINT `ord_customer_fk` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`),
  CONSTRAINT `ord_sub_fk` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions`(`id`) ON DELETE SET NULL,
  CONSTRAINT `ord_zone_fk` FOREIGN KEY (`delivery_zone_id`) REFERENCES `delivery_zones`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `order_items`;
CREATE TABLE `order_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `basket_id` BIGINT UNSIGNED NULL COMMENT 'Có giá trị nếu item thuộc giỏ',
  `quantity` SMALLINT UNSIGNED NOT NULL COMMENT 'Số gói đặt',
  `weight_kg` DECIMAL(8,3) NOT NULL COMMENT 'quantity × pack_weight_kg',
  `unit_price` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 nếu tính theo giá giỏ',
  `line_total` INT UNSIGNED NOT NULL DEFAULT 0,
  `fulfilled_quantity` SMALLINT UNSIGNED NULL COMMENT 'Số gói thực giao → tính tỷ lệ giao đủ',
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  KEY `oi_product_idx` (`product_id`),
  CONSTRAINT `oi_order_fk` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE CASCADE,
  CONSTRAINT `oi_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`),
  CONSTRAINT `oi_basket_fk` FOREIGN KEY (`basket_id`) REFERENCES `baskets`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 3. Phía cung: nông hộ báo sản lượng
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `supply_reports`;
CREATE TABLE `supply_reports` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `farmer_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `available_date` DATE NOT NULL COMMENT 'Ngày có thể thu hoạch',
  `quantity_kg` DECIMAL(8,2) NOT NULL,
  `source` ENUM('zalo','form','operator') NOT NULL DEFAULT 'form',
  `note` VARCHAR(255) NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `supply_unique` (`farmer_id`,`product_id`,`available_date`),
  KEY `supply_date_idx` (`available_date`,`product_id`),
  CONSTRAINT `sr_farmer_fk` FOREIGN KEY (`farmer_id`) REFERENCES `farmers`(`id`) ON DELETE CASCADE,
  CONSTRAINT `sr_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 4. Điều phối: dự báo + kế hoạch thu hoạch
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `forecasts`;
CREATE TABLE `forecasts` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `target_date` DATE NOT NULL COMMENT 'Ngày giao được dự báo',
  `generated_on` DATE NOT NULL COMMENT 'Ngày chạy dự báo',
  `method` ENUM('moving_average','exp_smoothing','tree_regression','manual') NOT NULL,
  `confirmed_kg` DECIMAL(8,2) NOT NULL DEFAULT 0 COMMENT 'Đơn đã xác nhận tại thời điểm chạy',
  `predicted_extra_kg` DECIMAL(8,2) NOT NULL DEFAULT 0 COMMENT 'Dự báo đơn phát sinh',
  `predicted_total_kg` DECIMAL(8,2) NOT NULL,
  `lower_kg` DECIMAL(8,2) NULL,
  `upper_kg` DECIMAL(8,2) NULL,
  `actual_kg` DECIMAL(8,2) NULL COMMENT 'Điền sau ngày giao → tính MAE/MAPE',
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `forecast_unique` (`product_id`,`target_date`,`generated_on`,`method`),
  CONSTRAINT `fc_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `harvest_plans`;
CREATE TABLE `harvest_plans` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `harvest_date` DATE NOT NULL,
  `delivery_date` DATE NOT NULL,
  `safety_margin_pct` DECIMAL(5,2) NOT NULL DEFAULT 10.00,
  `status` ENUM('draft','confirmed','sent','completed') NOT NULL DEFAULT 'draft',
  `created_by` BIGINT UNSIGNED NULL,
  `confirmed_by` BIGINT UNSIGNED NULL,
  `confirmed_at` TIMESTAMP NULL,
  `note` TEXT NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `hp_delivery_unique` (`delivery_date`),
  CONSTRAINT `hp_created_fk` FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE SET NULL,
  CONSTRAINT `hp_confirmed_fk` FOREIGN KEY (`confirmed_by`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `harvest_plan_items`;
CREATE TABLE `harvest_plan_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `harvest_plan_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `farmer_id` BIGINT UNSIGNED NULL,
  `confirmed_order_kg` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `forecast_extra_kg` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `available_stock_kg` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `suggested_kg` DECIMAL(8,2) NOT NULL COMMENT 'Hệ thống gợi ý',
  `final_kg` DECIMAL(8,2) NULL COMMENT 'Operator chốt',
  `received_kg` DECIMAL(8,2) NULL COMMENT 'Thực nhận từ nông hộ',
  `adjust_reason` VARCHAR(255) NULL,
  `farmer_confirmed_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `hpi_plan_fk` FOREIGN KEY (`harvest_plan_id`) REFERENCES `harvest_plans`(`id`) ON DELETE CASCADE,
  CONSTRAINT `hpi_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`),
  CONSTRAINT `hpi_farmer_fk` FOREIGN KEY (`farmer_id`) REFERENCES `farmers`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 5. Truy xuất: lô hàng + QR
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `batches`;
CREATE TABLE `batches` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(40) NOT NULL COMMENT 'Mã lô = nội dung QR, VD: F2H-260930-RM-NH01',
  `harvest_plan_item_id` BIGINT UNSIGNED NULL,
  `farmer_id` BIGINT UNSIGNED NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `quantity_kg` DECIMAL(8,2) NOT NULL,
  `harvested_at` DATETIME NOT NULL,
  `received_at` DATETIME NULL,
  `processed_at` DATETIME NULL,
  `packed_at` DATETIME NULL,
  `processing_note` VARCHAR(255) NULL,
  `storage_guide` TEXT NULL COMMENT 'Mặc định copy từ products',
  `best_before` DATE NULL,
  `quality_status` ENUM('pending','passed','rejected') NOT NULL DEFAULT 'pending',
  `qc_note` VARCHAR(255) NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `batches_code_unique` (`code`),
  CONSTRAINT `bt_hpi_fk` FOREIGN KEY (`harvest_plan_item_id`) REFERENCES `harvest_plan_items`(`id`) ON DELETE SET NULL,
  CONSTRAINT `bt_farmer_fk` FOREIGN KEY (`farmer_id`) REFERENCES `farmers`(`id`),
  CONSTRAINT `bt_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `order_item_batches`;
CREATE TABLE `order_item_batches` (
  `order_item_id` BIGINT UNSIGNED NOT NULL,
  `batch_id` BIGINT UNSIGNED NOT NULL,
  `quantity` SMALLINT UNSIGNED NOT NULL COMMENT 'Số gói lấy từ lô này',
  PRIMARY KEY (`order_item_id`,`batch_id`),
  CONSTRAINT `oib_item_fk` FOREIGN KEY (`order_item_id`) REFERENCES `order_items`(`id`) ON DELETE CASCADE,
  CONSTRAINT `oib_batch_fk` FOREIGN KEY (`batch_id`) REFERENCES `batches`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- 6. Phản hồi & chỉ số môi trường
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `feedbacks`;
CREATE TABLE `feedbacks` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `batch_id` BIGINT UNSIGNED NOT NULL,
  `order_id` BIGINT UNSIGNED NULL,
  `customer_id` BIGINT UNSIGNED NULL,
  `rating` TINYINT UNSIGNED NOT NULL COMMENT '1-5',
  `freshness_rating` TINYINT UNSIGNED NULL COMMENT '1-5',
  `comment` TEXT NULL,
  `status` ENUM('new','processing','resolved') NOT NULL DEFAULT 'new',
  `response` TEXT NULL,
  `resolved_by` BIGINT UNSIGNED NULL,
  `resolved_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `fb_batch_fk` FOREIGN KEY (`batch_id`) REFERENCES `batches`(`id`) ON DELETE CASCADE,
  CONSTRAINT `fb_order_fk` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fb_customer_fk` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL,
  CONSTRAINT `fb_resolver_fk` FOREIGN KEY (`resolved_by`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `waste_logs`;
CREATE TABLE `waste_logs` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `log_date` DATE NOT NULL,
  `product_id` BIGINT UNSIGNED NOT NULL,
  `batch_id` BIGINT UNSIGNED NULL,
  `quantity_kg` DECIMAL(8,2) NOT NULL,
  `reason` ENUM('surplus','damaged','expired','discounted') NOT NULL,
  `note` VARCHAR(255) NULL,
  `created_by` BIGINT UNSIGNED NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  KEY `waste_date_idx` (`log_date`),
  CONSTRAINT `wl_product_fk` FOREIGN KEY (`product_id`) REFERENCES `products`(`id`),
  CONSTRAINT `wl_batch_fk` FOREIGN KEY (`batch_id`) REFERENCES `batches`(`id`) ON DELETE SET NULL,
  CONSTRAINT `wl_user_fk` FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `packaging_returns`;
CREATE TABLE `packaging_returns` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `return_date` DATE NOT NULL,
  `customer_id` BIGINT UNSIGNED NULL,
  `order_id` BIGINT UNSIGNED NULL,
  `quantity_returned` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `quantity_reused` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  `note` VARCHAR(255) NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `pr_customer_fk` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL,
  CONSTRAINT `pr_order_fk` FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

